$(function(){var ai_company_name="3DM";var ai_3dm_url=SiteURL;var ai_3dm_url_local="http://localhost/3dm_app_new/";$(document).on("click",".ai-menu .dropdown-menu",function(e){e.stopPropagation()}).on("click","[data-ai-question-id]",function(e){if($("table.printable").hasClass("data-table-report"))$("table.data-table-report").dataTable().fnLengthChange(-1);$(".ai-heading").text($(this).find(".media-body p").text());$("[data-ai-helptext]").html("Loading...");$.post(SiteURL+"artificial_intelligence/ajax_processor.php",{question_id:$(this).attr("data-ai-question-id"),data:$("table.printable").text()},function(data){$("[data-ai-helptext]").html(data)})});$("[data-ai-get-questions]").click(function(){$.get(ai_3dm_url+"artificial_intelligence/ajax_get_questions.php",{page_url:(window.location.origin+window.location.pathname).replace(SiteURL,""),company_name:ai_company_name},function(data){$("[data-ai-helptext]").html(data)})})});